 /* ============================================================
    LUXE — main.js
    Accessibility-aware interactions
    ============================================================ */
 (function () {
   'use strict';

   /* --- Mobile navigation toggle ----------------------------- */
   const navToggle = document.getElementById('nav-toggle');
   const navList   = document.getElementById('primary-nav-list');

   if (navToggle && navList) {
     navToggle.addEventListener('click', () => {
       const expanded = navToggle.getAttribute('aria-expanded') === 'true';
       const willOpen = !expanded;

       navToggle.setAttribute('aria-expanded', String(willOpen));
       navToggle.setAttribute(
         'aria-label',
         willOpen ? 'Close navigation menu' : 'Open navigation menu'
       );

       navList.classList.toggle('is-open', willOpen);

       if (willOpen) {
         // Move focus to first nav link
         const first = navList.querySelector('a');
         if (first) first.focus();
       }
     });

     // Close nav on Escape
     document.addEventListener('keydown', (e) => {
       if (e.key === 'Escape' && navToggle.getAttribute('aria-expanded') === 'true') {
         navToggle.setAttribute('aria-expanded', 'false');
         navToggle.setAttribute('aria-label', 'Open navigation menu');
         navList.classList.remove('is-open');
         navToggle.focus();
       }
     });

     // Close nav when a link is activated (mobile)
     navList.querySelectorAll('a').forEach((link) => {
       link.addEventListener('click', () => {
         if (window.innerWidth < 768) {
           navToggle.setAttribute('aria-expanded', 'false');
           navToggle.setAttribute('aria-label', 'Open navigation menu');
           navList.classList.remove('is-open');
         }
       });
     });
   }

   /* --- Promo banner dismiss --------------------------------- */
   const promoClose  = document.getElementById('promo-close');
   const promoBanner = document.getElementById('promo-banner');
   const brand       = document.querySelector('.brand');

   if (promoClose && promoBanner) {
     promoClose.addEventListener('click', () => {
       promoBanner.hidden = true;
       // Return focus to a stable landmark — the brand/logo link
       if (brand) brand.focus();
     });
   }

   /* --- Cart -------------------------------------------------- */
   let cartCount = 0;
   const cartBtn      = document.getElementById('cart-btn');
   const cartCountEl  = document.getElementById('cart-count');
   const cartStatus   = document.getElementById('cart-status');

   function updateCartLabel() {
     if (!cartBtn) return;
     const label = cartCount === 0
       ? 'Shopping cart, empty'
       : `Shopping cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`;
     cartBtn.setAttribute('aria-label', label);

     if (cartCountEl) {
       if (cartCount > 0) {
         cartCountEl.textContent = cartCount;
         cartCountEl.removeAttribute('hidden');
       } else {
         cartCountEl.hidden = true;
       }
     }
   }

   document.querySelectorAll('.btn-cart').forEach((btn) => {
     btn.addEventListener('click', () => {
       const productName = btn.getAttribute('data-product');
       cartCount += 1;
       updateCartLabel();

       // Announce to screen readers via live region
       if (cartStatus) {
         cartStatus.textContent = ''; // reset so same product can be re-announced
         requestAnimationFrame(() => {
           cartStatus.textContent = `${productName || 'Item'} added to cart.`;
         });
       }
     });
   });

   /* --- Newsletter form --------------------------------------- */
   const newsletterForm   = document.getElementById('newsletter-form');
   const newsletterStatus = document.getElementById('newsletter-status');

   if (newsletterForm) {
     newsletterForm.addEventListener('submit', (e) => {
       e.preventDefault();
       const email = document.getElementById('newsletter-email');

       if (!email || !email.value) return;

       if (newsletterStatus) {
         newsletterStatus.textContent = `Thanks! We'll send updates to ${email.value}.`;
       }

       email.value = '';
     });
   }

   /* --- Countdown timers on deal cards ----------------------- */
   document.querySelectorAll('[data-deal-end]').forEach((el) => {
     const endTime = parseInt(el.getAttribute('data-deal-end'), 10);

     function tick() {
       const diff = endTime - Date.now();
       if (diff <= 0) {
         el.textContent = 'Deal ended';
         return;
       }
       const h = Math.floor(diff / 3600000);
       const m = Math.floor((diff % 3600000) / 60000);
       const s = Math.floor((diff % 60000) / 1000);
       const pad = (n) => String(n).padStart(2, '0');
       el.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
     }

     tick();
     setInterval(tick, 1000);
   });
 })();

