const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // --- Full audit at desktop width ---
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const desktop = await page.evaluate(async () => await window.axe.run(document, {
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','best-practice'] }
  }));

  // --- Narrow viewport (320 px reflow) ---
  await page.setViewportSize({ width: 320, height: 568 });
  await page.reload({ waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const narrow = await page.evaluate(async () => await window.axe.run(document, {
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','best-practice'] }
  }));

  // --- Mobile nav open state ---
  await page.setViewportSize({ width: 375, height: 667 });
  await page.reload({ waitUntil: 'load' });
  await page.click('#nav-toggle');
  await page.waitForTimeout(200);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const mobileNavOpen = await page.evaluate(async () => await window.axe.run(document, {
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','best-practice'] }
  }));

  await browser.close();

  const fmt = v => ({
    id: v.id, impact: v.impact,
    description: v.description,
    nodes: v.nodes.map(n => ({ target: n.target, html: n.html.slice(0,120), failureSummary: n.failureSummary }))
  });

  const result = {
    desktop:  { violations: desktop.violations.map(fmt),  passes: desktop.passes.length },
    narrow:   { violations: narrow.violations.map(fmt),   passes: narrow.passes.length },
    mobileNav:{ violations: mobileNavOpen.violations.map(fmt), passes: mobileNavOpen.passes.length },
  };

  console.log(JSON.stringify(result, null, 2));
})();
