const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });

  // 1. Collect all focusable elements in tab order
  const focusOrder = await page.evaluate(() => {
    const sel = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
    return [...document.querySelectorAll(sel)].map(el => ({
      tag: el.tagName,
      text: (el.textContent || el.getAttribute('aria-label') || el.getAttribute('placeholder') || '').trim().slice(0,60),
      tabindex: el.tabIndex,
      ariaLabel: el.getAttribute('aria-label'),
      ariaHidden: el.getAttribute('aria-hidden'),
    }));
  });
  console.log('=== TAB ORDER ===');
  focusOrder.forEach((el, i) => console.log(i, el.tag, JSON.stringify(el.text), el.ariaLabel ? `[${el.ariaLabel}]` : ''));

  // 2. Check headings outline
  const headings = await page.evaluate(() =>
    [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h => ({
      level: parseInt(h.tagName[1]), text: h.textContent.trim().slice(0,80)
    }))
  );
  console.log('\n=== HEADING OUTLINE ===');
  headings.forEach(h => console.log('  '.repeat(h.level-1) + `H${h.level}: ${h.text}`));

  // 3. Check images for alt / role
  const images = await page.evaluate(() =>
    [...document.querySelectorAll('img,[role="img"]')].map(el => ({
      tag: el.tagName, alt: el.getAttribute('alt'), role: el.getAttribute('role'),
      ariaLabel: el.getAttribute('aria-label')
    }))
  );
  console.log('\n=== IMAGES ===');
  images.forEach(img => console.log(img.tag, 'alt=', img.alt, 'role=', img.role, 'aria-label=', img.ariaLabel));

  // 4. Check nav landmarks
  const navs = await page.evaluate(() =>
    [...document.querySelectorAll('nav,[role="navigation"]')].map(n => ({
      ariaLabel: n.getAttribute('aria-label'),
      ariaLabelledby: n.getAttribute('aria-labelledby'),
    }))
  );
  console.log('\n=== NAV LANDMARKS ===');
  navs.forEach(n => console.log(n.ariaLabel));

  // 5. Check all interactive buttons have accessible names
  const buttons = await page.evaluate(() =>
    [...document.querySelectorAll('button')].map(b => ({
      text: b.textContent.trim().slice(0,60),
      ariaLabel: b.getAttribute('aria-label'),
      type: b.type,
    }))
  );
  console.log('\n=== BUTTONS ===');
  buttons.forEach(b => {
    const name = b.ariaLabel || b.text;
    const ok = name.length > 0;
    console.log(ok ? '✓' : '✗', JSON.stringify(name));
  });

  // 6. Verify skip link is first focusable
  const firstFocusable = await page.evaluate(() => {
    const el = document.querySelector('a[href],button');
    return { tag: el.tagName, href: el.getAttribute('href'), text: el.textContent.trim() };
  });
  console.log('\n=== FIRST FOCUSABLE ===', firstFocusable);

  // 7. Check main has tabindex=-1 for skip link target
  const mainTabIndex = await page.evaluate(() => {
    const m = document.getElementById('maincontent');
    return { tabindex: m?.getAttribute('tabindex'), id: m?.id };
  });
  console.log('\n=== MAIN ELEMENT ===', mainTabIndex);

  // 8. Check aria-live regions
  const liveRegions = await page.evaluate(() =>
    [...document.querySelectorAll('[aria-live],[role="status"],[role="alert"]')].map(el => ({
      tag: el.tagName, role: el.getAttribute('role'), live: el.getAttribute('aria-live'), id: el.id
    }))
  );
  console.log('\n=== LIVE REGIONS ===');
  liveRegions.forEach(r => console.log(r));

  await browser.close();
})();
